-- GENERATED by `dsx build` (the <server> document compile step) — never hand-edit.
-- Re-runnable by construction: create-if-not-exists + additive column convergence,
-- so applying it to a live database is how a schema change reaches it.

-- The platform preamble: every policy calls auth.uid() and runs as anon/authenticated.
-- A hosted Supabase project already provides all three; a bare Postgres does not.
create schema if not exists auth;
do $$ begin
  if not exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'auth' and p.proname = 'uid'
  ) then
    create function auth.uid() returns uuid language sql stable as $fn$
      select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid
    $fn$;
  end if;
end $$;
do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then create role anon nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then create role authenticated nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'service_role') then create role service_role nologin; end if;
end $$;
grant usage on schema auth to anon, authenticated;
grant usage on schema public to anon, authenticated;

create table if not exists dsx_note (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid(),
  body text,
  title text,
  created_at timestamptz not null default now()
);
alter table dsx_note add column if not exists body text;
alter table dsx_note add column if not exists title text;
alter table dsx_note enable row level security;
alter table dsx_note force row level security;
drop policy if exists dsx_note_owner_all on dsx_note;
create policy dsx_note_owner_all on dsx_note for all using (owner_id = auth.uid()) with check (owner_id = auth.uid());
revoke all on dsx_note from anon;
grant select, insert, update, delete on dsx_note to authenticated;

